#!/bin/sh
# The CRDs an environment applies (system/crds, generated by scripts/vendor-crds, each annotated Prune=false), applied
# server-side as Argo CD's field manager: by the bootstrap before Argo CD's ApplicationSets, and by just dev and just
# testbed on a running cluster before they push a commit. A component whose chart stops rendering a CRD would otherwise
# have Argo CD prune it, and every object of its kind with it, before the bootstrap ran.
# Each environment applies its list, system/crds/environments/<env>.txt (lab crds generate: its components' CRDs and
# those of the kinds its renders use); the sandbox (dev), which has none, applies every one; the seed is production's
# first install. A CRD that leaves a list stays in the cluster: none is ever deleted here
# (docs/superpowers/specs/2026-11-25-testbed-capacity-design.md).
# Usage: apply-crds.sh <repository root> <environment>. Env: KUBECONFIG.
set -eu
root=$1
env=${2:?apply-crds.sh: usage: apply-crds.sh <repository root> <environment>}
[ "$env" = seed ] && env=prod
list="$root/system/crds/environments/$env.txt"
apply() { kubectl apply --server-side --field-manager argocd-controller --force-conflicts -f - >/dev/null; }
if [ -f "$list" ]; then
	# Every listed file first: a cat failing inside the pipeline would leave kubectl applying a partial list, and succeed
	# (a redirect, not a pipe: exit leaves the script)
	while read -r file; do
		case "$file" in '#'* | '') continue ;; esac
		[ -f "$root/system/crds/files/$file" ] || {
			echo "apply-crds.sh: $list names $file, which system/crds/files lacks: run lab crds generate" >&2
			exit 1
		}
	done < "$list"
	grep -v '^#' "$list" | while read -r file; do
		[ -n "$file" ] || continue
		echo ---
		cat "$root/system/crds/files/$file"
	done | apply
elif [ "$env" = dev ]; then
	helm template crds "$root/system/crds" | apply
else
	echo "apply-crds.sh: no CRD list for environment $env (system/crds/environments): add it to lab crds' Environments (cli/internal/crds) and run lab crds generate" >&2
	exit 1
fi
